for r0 in starts:
    for c0,c1 in [(0,6),(12,18)]:
        # assess occupied source chunks and copy reflected pixels into empty partner
        A=[grid[r][c0:c0+5] for r in range(r0,min(r0+5,26))]
        B=[grid[r][c1:c1+5] for r in range(r0,min(r0+5,26))]
